// HasDashboard applies the HasEdge predicate on the "dashboard" edge.
func HasDashboard() predicate.BiDashboardRevision {
	return predicate.BiDashboardRevision(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, DashboardTable, DashboardColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasDashboardWith applies the HasEdge predicate on the "dashboard" edge with a given conditions (other predicates).
func HasDashboardWith(preds ...predicate.BiDashboard) predicate.BiDashboardRevision {
	return predicate.BiDashboardRevision(func(s *sql.Selector) {
		step := newDashboardStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BiDashboardRevision) predicate.BiDashboardRevision {
	return predicate.BiDashboardRevision(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BiDashboardRevision) predicate.BiDashboardRevision {
	return predicate.BiDashboardRevision(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BiDashboardRevision) predicate.BiDashboardRevision {
	return predicate.BiDashboardRevision(sql.NotPredicates(p))
}
